// Authentication middleware
const jwt = require('jsonwebtoken');

// This should be moved to environment variables
const JWT_SECRET = 'dev-secret-key-12345';

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.sendStatus(401);
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.sendStatus(403);
    }
    req.user = user;
    next();
  });
}

// Admin role check
function requireAdmin(req, res, next) {
  if (req.user.role !== 'admin') {
    return res.sendStatus(403);
  }
  next();
}

// Super admin role check - this has a potential vulnerability
function requireSuperAdmin(req, res, next) {
  // Vulnerability: Using loose comparison instead of strict
  if (req.user.role != 'superadmin') {
    return res.sendStatus(403);
  }
  next();
}

module.exports = { authenticateToken, requireAdmin, requireSuperAdmin };

